package ec.edu.monster.controladores;
import ec.edu.monster.modelos.*;import ec.edu.monster.servicios.ClienteSoapEureka;import jakarta.enterprise.context.RequestScoped;import jakarta.inject.Inject;import jakarta.inject.Named;import java.math.BigDecimal;import java.util.*;
/** Casos de uso del panel. No hay XML ni llamadas HTTP en las vistas. */
@Named @RequestScoped public class BancaBean {@Inject private SesionBean sesion;private final ClienteSoapEureka soap=new ClienteSoapEureka();private List<CuentaVista> cuentas=List.of();private List<MovimientoVista> movimientos=List.of();private String cuentaId,origen,destino,tipo,transaccionId,mensaje;private BigDecimal monto;public void cargarCuentas(){try{cuentas=soap.cuentas(sesion.getToken());}catch(Exception e){error(e);}}public void consultarMovimientos(){try{movimientos=soap.movimientos(sesion.getToken(),cuentaId);}catch(Exception e){error(e);}}public void transferir(){try{soap.transferir(sesion.getToken(),origen,destino,monto);mensaje="Transferencia completada y registrada en auditoría.";cargarCuentas();}catch(Exception e){error(e);}}public void registrar(){try{soap.movimiento(sesion.getToken(),tipo.toUpperCase(),cuentaId,monto);mensaje="Operación registrada correctamente.";cargarCuentas();}catch(Exception e){error(e);}}public void reversar(){try{soap.reversar(sesion.getToken(),transaccionId);mensaje="Reversa registrada correctamente.";cargarCuentas();}catch(Exception e){error(e);}}private void error(Exception e){mensaje=(e.getMessage()==null?"No se pudo completar la operación.":e.getMessage().replaceAll("(?s)<[^>]*>","").trim());}public List<CuentaVista> getCuentas(){if(cuentas.isEmpty()&&sesion.getActiva())cargarCuentas();return cuentas;}public List<MovimientoVista> getMovimientos(){return movimientos;}public String getCuentaId(){return cuentaId;}public void setCuentaId(String v){cuentaId=v;}public String getOrigen(){return origen;}public void setOrigen(String v){origen=v;}public String getDestino(){return destino;}public void setDestino(String v){destino=v;}public String getTipo(){return tipo;}public void setTipo(String v){tipo=v;}public String getTransaccionId(){return transaccionId;}public void setTransaccionId(String v){transaccionId=v;}public BigDecimal getMonto(){return monto;}public void setMonto(BigDecimal v){monto=v;}public String getMensaje(){return mensaje;}}
